#include <cassert>
#include <cstdio>
using namespace std;

int n, ans;

bool not_prime[1000005];
int primes[500000], pcnt = 0;

void get_primes() {
    not_prime[1] = true;
    for (int i = 2; i <= n; ++i) {
        if (!not_prime[i]) {
            primes[pcnt++] = i;
            for (int j = 2; i * j <= n; ++j) {
                not_prime[i * j] = true;
            }
        }
    }
}

int main() {
    scanf("%d", &n);
    get_primes();
    for (int i = 0; i < pcnt && primes[i] <= n / 2; ++i)
        if (!not_prime[n - primes[i]])
            ans++;
    printf("%d\n", ans);
    return 0;
}

#include <cstdio>
#include <algorithm>
using namespace std;

const int N = 2005;

int n, t;
int v[N], s[N], p[N];
double ans;

bool cmp(int x, int y) {
    return s[x] < s[y];
}

int main() {
    scanf("%d%d", &n, &t);
    for (int i = 1; i <= n; i++) {
        scanf("%d%d", &v[i], &s[i]);
        p[i] = i;
    }
    sort(p + 1, p + n + 1, cmp);
    int ss = 0, sv = 0;
    for (int i = 1; i <= n; i++) {
        int cv = v[p[i]], cs = s[p[i]];
        if (ss + cs * cv > t * (sv + cv)) {
            double k = (double)(t * sv - ss) / (cs - t);
            ans = max(ans, sv + k);
            break;
        }
        ss += cs * cv;
        sv += cv;
    }
    if (ss == sv * t) ans = max(ans, (double) sv);
    sv = ss = 0;
    for (int i = n; i >= 1; i--) {
        int cv = v[p[i]], cs = s[p[i]];
        if (ss + cs * cv < t * (sv + cv)) {
            double k = (double)(t * sv - ss) / (cs - t);
            ans = max(ans, sv + k);
            break;
        }
        ss += cs * cv;
        sv += cv;
    }
    if (ss == sv * t) ans = max(ans, (double) sv);
    printf("%.3lf\n", ans);
    return 0;
}
